s=s[:start]+"fun DrawScope.shape(piece: Piece, center: Offset, radius: Float, silhouette: Boolean = false, faded: Boolean = false, glow: Boolean = false) {\n    val c=Palette[piece.color % Palette.size]\n    fun tone(a:Color,b:Color,t:Float)=Color(a.red+(b.red-a.red)*t,a.green+(b.green-a.green)*t,a.blue+(b.blue-a.blue)*t,1f)\n    val dark=tone(c,Color(0xFF191444),.59f)\n    val rim=tone(c,Color.White,.58f)\n    val path=Path().apply {\n        fun polygon(points:List<Offset>) {\n            // Soft moulded corners, not sharp flat polygons.\n            fun mix(a:Offset,b:Offset,t:Float)=a+(b-a)*t\n            val n=points.size\n            for(i in 0 until n) {\n                val prev=points[(i+n-1)%n];val now=points[i];val next=points[(i+1)%n]\n                val a=mix(now,prev,.15f);val b=mix(now,next,.15f)\n                if(i==0)moveTo(a.x,a.y) else lineTo(a.x,a.y)\n                quadraticBezierTo(now.x,now.y,b.x,b.y)\n            }\n            close()\n        }\n        when(piece.shape) {\n            Shape.CIRCLE -> addOval(Rect(center-Offset(radius*.94f,radius*.94f),Size(radius*1.88f,radius*1.88f)))\n            Shape.SQUARE -> addRoundRect(RoundRect(Rect(center-Offset(radius*.87f,radius*.87f),Size(radius*1.74f,radius*1.74f)),CornerRadius(radius*.30f)))\n            Shape.ARCH -> {\n                fillType=PathFillType.EvenOdd\n                moveTo(center.x-radius*.85f,center.y+radius*.82f)\n                lineTo(center.x-radius*.85f,center.y-radius*.06f)\n                cubicTo(center.x-radius*.85f,center.y-radius*1.23f,center.x+radius*.85f,center.y-radius*1.23f,center.x+radius*.85f,center.y-radius*.06f)\n                lineTo(center.x+radius*.85f,center.y+radius*.82f);close()\n                addRoundRect(RoundRect(Rect(center.x-radius*.34f,center.y-radius*.12f,center.x+radius*.34f,center.y+radius*1.1f),CornerRadius(radius*.31f)))\n            }\n            Shape.CHEVRON -> polygon(listOf(Offset(-.91f,-.81f),Offset(0f,-.24f),Offset(.91f,-.81f),Offset(.91f,.18f),Offset(0f,.91f),Offset(-.91f,.18f)).map {center+it*radius})\n            else -> {\n                val n=when(piece.shape){Shape.TRIANGLE->3;Shape.DIAMOND->4;Shape.HEXAGON->6;else->10}\n                polygon(List(n){i->\n                    val a=-PI/2+2*PI*i/n\n                    val r=if(piece.shape==Shape.STAR && i%2==1)radius*.51f else radius\n                    center+Offset(cos(a).toFloat()*r,sin(a).toFloat()*r)\n                })\n            }\n        }\n    }\n    rotate(piece.turn*90f,center) {\n        if(glow) drawCircle(Brush.radialGradient(listOf(Gold.copy(alpha=.50f),Color.Transparent),center,radius*1.42f),radius*1.42f,center)\n        if (silhouette || faded) {\n            val socket=if(silhouette)Color(0xFF51486F) else tone(c,Color(0xFF664933),.48f)\n            drawPath(path,Color(0xFF5B3724).copy(alpha=.47f),style=Stroke(radius*.13f,join=StrokeJoin.Round))\n            drawPath(path,Brush.linearGradient(listOf(tone(socket,Color.Black,.32f),socket,tone(socket,Color.White,.30f)),center-Offset(radius,radius),center+Offset(radius,radius)))\n            drawPath(path,Color.White.copy(alpha=.67f),style=Stroke(radius*.045f,join=StrokeJoin.Round))\n        } else {\n            // Cast shadow, rounded extrusion, bevel and broad glossy highlights.\n            drawOval(Brush.radialGradient(listOf(Color(0xFF241342).copy(alpha=.40f),Color.Transparent),center+Offset(0f,radius*.77f),radius*1.05f),center+Offset(-radius*1.04f,radius*.49f),Size(radius*2.08f,radius*.56f))\n            for(i in 9 downTo 1) translate(top=radius*.019f*i) {\n                drawPath(path,tone(dark,c,(9-i)/11f))\n            }\n            drawPath(path,Brush.linearGradient(listOf(rim,tone(c,Color.White,.25f),c,tone(c,Color.Black,.25f)),center-Offset(radius*.75f,radius),center+Offset(radius*.75f,radius)))\n            drawPath(path,Brush.linearGradient(listOf(Color.White.copy(alpha=.9f),rim.copy(alpha=.65f),dark.copy(alpha=.95f)),center-Offset(radius,radius),center+Offset(radius,radius)),style=Stroke(radius*.07f,join=StrokeJoin.Round))\n            clipPath(path) {\n                drawOval(Brush.radialGradient(listOf(Color.White.copy(alpha=.58f),Color.Transparent),center-Offset(radius*.35f,radius*.49f),radius*.68f),center-Offset(radius*.91f,radius*.92f),Size(radius*1.43f,radius*.80f))\n                drawOval(Color.White.copy(alpha=.57f),center-Offset(radius*.45f,radius*.55f),Size(radius*.43f,radius*.12f))\n                drawOval(Color.White.copy(alpha=.29f),center-Offset(radius*.50f,radius*.36f),Size(radius*.13f,radius*.10f))\n            }\n            if(glow) drawPath(path,Gold,style=Stroke(radius*.09f,join=StrokeJoin.Round))\n        }\n    }\n}\n"+"\n"+s[end:]
