# Preserve navigation and accessibility test tags elsewhere.
def replace_composable_body(s, name, body):
    m=re.search(r'fun '+name+r'\([^\n]*\)\s*\{',s)
    assert m, name
    start=m.end()-1
    # all existing functions below have braces balanced and no literal brace in string
    depth=1;i=start+1
    while depth and i<len(s):
        if s[i]=="{": depth+=1
        elif s[i]=="}": depth-=1
        i+=1
    assert depth==0
    return s[:start]+"{"+body+"}"+s[i:]
